using System;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;

public sealed class BCombatInitialHealthTests {
 static BCombatFormation Formation()=>new BCombatFormation("train",BCombatMode.Solo,BCombatBattlefield.ExternalVertical,new[]{new BCombatSlot("front","op_kyle"),new BCombatSlot("cargo")});
 static BCombatHpBinding Initial(string id,int max,int hp){var ctor=typeof(BCombatHpBinding).GetConstructor(new[]{typeof(string),typeof(int),typeof(int)});Assert.NotNull(ctor,"Missing explicit initial HP binding");try{return (BCombatHpBinding)ctor.Invoke(new object[]{id,max,hp});}catch(TargetInvocationException e){throw e.InnerException;}}
 static BCombatHpBinding[] Bindings(int hp=70)=>new[]{Initial("train",1000,800),Initial("front",20,10),Initial("cargo",100,100),Initial("op_kyle",200,hp)};
 static BCombatLocalModel Model(BCombatHpBinding[] bindings,int capacity=30)=>BCombatLocalModel.CreateWithCarriageTransfer(Formation(),bindings,capacity,BCombatAuthority.UnitySolo);
 static BCombatSingleTargetReceipt Heal(BCombatLocalModel model,string id,string target,int amount,long tick){var method=typeof(BCombatLocalModel).GetMethod("ApplyResolvedLivingSkillHeal");Assert.NotNull(method,"Missing living skill heal command");try{return (BCombatSingleTargetReceipt)method.Invoke(model,new object[]{id,target,amount,tick});}catch(TargetInvocationException e){throw e.InnerException;}}
 static int Excess(BCombatSingleTargetReceipt receipt){var property=receipt.GetType().GetProperty("DerivedExcess");Assert.NotNull(property,"Living-skill excess must remain distinct from lifesteal");return (int)property.GetValue(receipt);}
 [Test] public void InitialCurrentHpIsAnImmutableDefinitionWithoutFakeDamageEvents(){var bindings=Bindings();var model=Model(bindings);Assert.AreEqual(70,model.Hp("op_kyle"));Assert.AreEqual(800,model.Hp("train"));Assert.AreEqual(10,model.Hp("front"));Assert.IsEmpty((JArray)JObject.Parse(model.CaptureLocal())["events"]);var copy=BCombatLocalModel.RestoreLocal(model.CaptureLocal(),Formation(),bindings,30,BCombatAuthority.UnitySolo);Assert.AreEqual(model.CaptureLocal(),copy.CaptureLocal());}
 [TestCase(-1)][TestCase(201)] public void InitialHpOutsideMaximumIsRejected(int hp){Assert.Throws<ArgumentOutOfRangeException>(()=>Initial("op_kyle",200,hp));}
 [Test] public void DefaultFullHealthPreservesLegacyBytes(){var old=new[]{new BCombatHpBinding("train",1000),new BCombatHpBinding("front",20),new BCombatHpBinding("cargo",100),new BCombatHpBinding("op_kyle",200)};var explicitFull=old.Select(b=>Initial(b.TargetId,b.MaxHp,b.MaxHp)).ToArray();Assert.AreEqual(Model(old).CaptureLocal(),Model(explicitFull).CaptureLocal());}
 [Test] public void DamageShieldAndSkillHealingShareOneHpOwnerAndReplay(){var bindings=Bindings();var model=Model(bindings);model.ApplyResolvedShield("shield","op_kyle",new CombatShieldSource("op_kyle","shield",0),30,50,0);var damage=model.ApplyResolvedDamage("damage","op_kyle",50,1);Assert.AreEqual(30,damage.Absorbed);Assert.AreEqual(20,damage.HpLoss);Assert.AreEqual(50,model.Hp("op_kyle"));var heal=Heal(model,"heal","op_kyle",170,2);Assert.AreEqual(150,heal.HpGain);Assert.AreEqual(20,Excess(heal));Assert.AreEqual(200,model.Hp("op_kyle"));var before=model.CaptureLocal();Assert.AreSame(heal,Heal(model,"heal","op_kyle",170,2));Assert.Throws<InvalidOperationException>(()=>Heal(model,"heal","op_kyle",171,2));Assert.AreEqual(before,model.CaptureLocal());var restored=BCombatLocalModel.RestoreLocal(before,Formation(),bindings,30,BCombatAuthority.UnitySolo);Assert.AreEqual(before,restored.CaptureLocal());Assert.AreEqual(20,Excess(Heal(restored,"heal","op_kyle",170,2)));}
 [Test] public void DownOrDefeatedTrainCannotHealOrCreateExcess(){var down=Model(Bindings(0));var receipt=Heal(down,"down","op_kyle",100,0);Assert.AreEqual(0,receipt.HpGain);Assert.AreEqual(0,Excess(receipt));Assert.AreEqual(0,down.Hp("op_kyle"));var model=Model(Bindings());model.ApplyResolvedDamage("terminal","train",1000,1);receipt=Heal(model,"late","op_kyle",300,2);Assert.AreEqual(0,receipt.HpGain);Assert.AreEqual(0,Excess(receipt));Assert.AreEqual(70,model.Hp("op_kyle"));}
 [Test] public void WrongTargetCapacityAndClockFailuresDoNotMutateHealth(){var model=Model(Bindings(),1);var before=model.CaptureLocal();Assert.Throws<InvalidOperationException>(()=>Heal(model,"train-heal","train",1,0));Assert.AreEqual(before,model.CaptureLocal());Heal(model,"one","op_kyle",1,1);before=model.CaptureLocal();Assert.Throws<InvalidOperationException>(()=>Heal(model,"two","op_kyle",1,2));Assert.AreEqual(before,model.CaptureLocal());var timed=Model(Bindings());Heal(timed,"first","op_kyle",1,2);before=timed.CaptureLocal();Assert.Throws<InvalidOperationException>(()=>Heal(timed,"earlier","op_kyle",1,1));Assert.AreEqual(before,timed.CaptureLocal());}
 [Test] public void ReplayedStateCannotChangeInitialHpOrHealMagnitude(){var bindings=Bindings();var model=Model(bindings);Heal(model,"heal","op_kyle",20,1);var saved=model.CaptureLocal();Assert.Throws<ArgumentException>(()=>BCombatLocalModel.RestoreLocal(saved,Formation(),Bindings(71),30,BCombatAuthority.UnitySolo));var changed=JObject.Parse(saved);changed["events"][0]["magnitude"]=21;Assert.Throws<ArgumentException>(()=>BCombatLocalModel.RestoreLocal(changed.ToString(),Formation(),bindings,30,BCombatAuthority.UnitySolo));}
}
